class Solution:
    def hasMatch(self, s: str, p: str) -> bool:
        left, right = p.split("*")
        start = s.find(left)
        if start == -1:
            return False
        return s.find(right, start + len(left)) > 0

class Solution:
    def hasMatch(self, s: str, p: str) -> bool:
        if len(p) >= len(s):
            return False
        left, right = p.split("*")
        start = s.find(left)
        if start == -1:
            return False
        return s.find(right, start + len(left)) != -1
